def _unpack(blob):
    return zlib.decompress(base64.b64decode("".join(blob.split()))).decode().split("\n")


def load():
    """Return (common_words, proper_words) as two sets."""
    return set(_unpack(_COMMON)), set(_unpack(_PROPER))
